using Finora.Domain;using Finora.Infrastructure;using Microsoft.EntityFrameworkCore;namespace Finora.IntegrationTests;public sealed class FinanceStoreTests:IAsyncLifetime{private readonly string _dbPath=Path.Combine(Path.GetTempPath(),$"finora-test-{Guid.NewGuid():N}.db");private FinanceStore _store=null!;public async Task InitializeAsync(){var o=new DbContextOptionsBuilder<FinoraDbContext>().UseSqlite($"Data Source={_dbPath}").Options;var f=new TestFactory(o);_store=new FinanceStore(f,new DatabaseInitializer(f));await _store.InitializeAsync();}public Task DisposeAsync(){try{File.Delete(_dbPath);File.Delete(_dbPath+"-wal");File.Delete(_dbPath+"-shm");}catch(IOException){}return Task.CompletedTask;}[Fact]public async Task Transfer_IsAtomicDoubleEntryAndNetZero(){var a=new Account{Name="Bank",Type=AccountType.Bank,Currency="INR",OpeningBalanceMinor=10000};var b=new Account{Name="Wallet",Type=AccountType.DigitalWallet,Currency="INR"};await _store.SaveAccountAsync(a);await _store.SaveAccountAsync(b);await _store.RecordTransferAsync(a.Id,b.Id,2500,DateTimeOffset.UtcNow,"test");var accounts=await _store.GetAccountsAsync();Assert.Equal(7500,accounts.Single(x=>x.Id==a.Id).BalanceMinor);Assert.Equal(2500,accounts.Single(x=>x.Id==b.Id).BalanceMinor);Assert.Equal(10000,accounts.Sum(x=>x.BalanceMinor));}[Fact]public async Task RecurrenceProcessing_IsIdempotent(){var a=new Account{Name="Bank",Type=AccountType.Bank,Currency="INR"};await _store.SaveAccountAsync(a);var today=DateOnly.FromDateTime(DateTime.Today);await _store.SaveRecurrenceRuleAsync(new RecurrenceRule{Name="Rent",Frequency=RecurrenceFrequency.Monthly,StartsOn=today,NextDueOn=today,DayOfMonth=today.Day,TransactionType=TransactionType.Expense,AmountMinor=5000,Currency="INR",AccountId=a.Id});Assert.Equal(1,await _store.ProcessDueRecurrencesAsync(today));Assert.Equal(0,await _store.ProcessDueRecurrencesAsync(today));}private sealed class TestFactory(DbContextOptions<FinoraDbContext> options):IDbContextFactory<FinoraDbContext>{public FinoraDbContext CreateDbContext()=>new(options);public Task<FinoraDbContext>CreateDbContextAsync(CancellationToken cancellationToken=default)=>Task.FromResult(CreateDbContext());}}
